def subtract(a, b):
    def merge_intervals(intervals):
        """Merge overlapping intervals and return sorted disjoint intervals."""
        if not intervals:
            return []

        # Filter out empty intervals and sort by start
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Non-overlapping, add as new interval
                merged.append([start, end])

        return merged

    # Merge intervals in a
    a_merged = merge_intervals(a)
    # Merge intervals in b
    b_merged = merge_intervals(b)

    if not a_merged:
        return []
    if not b_merged:
        return a_merged

    result = []

    for a_start, a_end in a_merged:
        current_start = a_start

        for b_start, b_end in b_merged:
            # No overlap between [current_start, a_end) and [b_start, b_end)
            if b_end <= current_start or b_start >= a_end:
                continue

            # Add the part before b_start (if any)
            if current_start < b_start:
                result.append([current_start, b_start])

            # Move current_start past the b interval
            current_start = max(current_start, b_end)

            if current_start >= a_end:
                break

        # Add remaining part of a interval (if any)
        if current_start < a_end:
            result.append([current_start, a_end])

    return result

